    dkg_id: str,
    round_no: int,
    action: str,
    node: object,
    replacement: object,
    key: object,
) -> str:
    """审批单 message 必须逐字一致的紧凑 JSON（键序固定）。

    形如 {"dkg_id":"D","round":R,"action":"A","node":N,
    "replacement":X,"key":K}，N/X/K 为字符串或 null。"""
    return json.dumps(
        {
            "dkg_id": dkg_id,
            "round": round_no,
            "action": action,
            "node": node,
            "replacement": replacement,
            "key": key,
        },
        ensure_ascii=False,
        separators=(",", ":"),
    )

