def _dispatch_events_strict(self, wallet_id: str) -> list[dict]:
    """返回该钱包全部 chain_dispatch_requested 事件（按 seq 升序）并
    逐条严格校验**形状**（外层七字段键序、request_id==dispatch_id、
    actor_id 为安全标识、reason 为 null、details 恰为五键 V 且键序
    固定、各值合法）。

    这里只做与现场无关的形状校验；与账本/策略/审批单的语义复核在
    :meth:`_reconcile_chain_dispatch_events` 按事件 seq 完成。任何
    形状畸形都是不可对账现场（RecoveryError）。纯只读，不分配 seq。"""
    # 用 events_by_type 而非按 request_id 分组：后者会丢掉 request_id
    # 为 null/非字符串的畸形事件，必须让它们也进入严格校验而非被静默
    # 忽略。
    events = self._audit.events_by_type(
        wallet_id, audit.TYPE_CHAIN_DISPATCH_REQUESTED
    )
    seen: set[str] = set()
    for event in events:
        if list(event) != list(_AUDIT_OUTER_KEY_ORDER):
            raise RecoveryError(
                f"wallet {wallet_id!r} has a chain_dispatch_requested "
                "event whose outer fields are out of the canonical order"
            )
        dispatch_id = event.get("request_id")
        actor_id = event.get("actor_id")
        if (
            not isinstance(dispatch_id, str)
            or not ROTATION_ID_RE.match(dispatch_id)
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} has a chain_dispatch_requested "
                "event with a malformed dispatch_id"
            )
        if dispatch_id in seen:
            raise RecoveryError(
                f"wallet {wallet_id!r} has multiple "
                f"chain_dispatch_requested events for {dispatch_id!r}"
            )
        seen.add(dispatch_id)
        if not (
            isinstance(actor_id, str) and ROTATION_ID_RE.match(actor_id)
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} chain_dispatch_requested "
                f"{dispatch_id!r} has a malformed approval_request_id"
            )
        if event.get("reason") is not None:
            raise RecoveryError(
                f"wallet {wallet_id!r} chain_dispatch_requested "
                f"{dispatch_id!r} has a non-null reason"
            )
        details = event.get("details")
        if (
            not isinstance(details, dict)
            or list(details) != list(self._DISPATCH_VIEW_KEY_ORDER)
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} chain_dispatch_requested "
                f"{dispatch_id!r} has malformed details"
            )
        if details["dispatch_id"] != dispatch_id:
            raise RecoveryError(
                f"wallet {wallet_id!r} chain_dispatch_requested "
                f"{dispatch_id!r} details dispatch_id disagrees with "
                "its request_id"
            )
        for name in ("operation_id", "adapter_id", "chain_id"):
            value = details[name]
            if not isinstance(value, str) or not ROTATION_ID_RE.match(
                value
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} chain_dispatch_requested "
                    f"{dispatch_id!r} has a malformed {name}"
                )
        if details["state"] != "requested":
            raise RecoveryError(
                f"wallet {wallet_id!r} chain_dispatch_requested "
                f"{dispatch_id!r} has a state other than requested"
            )
    return events

def _reconcile_chain_dispatch_events(self, wallet_id: str) -> None:
    """按 seq 严格复核全部 chain_dispatch_requested 事件（调用方须持
    钱包事务锁）。

    每条事件都以其**提交之前**的现场复核在线首提的全部前置：

    - 操作在账本中存在、提交点之前无该操作的
      asset_operation_committed（当时为 pending）；
    - 每个操作至多一条派发事件（同 dispatch_id 重复已在形状校验
      拦截）；
    - 事前该资产跨链确认策略（该事件 seq 之前最后一条 chain_policy）
      已启用且 chain_id 与 details 一致；
    - 同钱包审批单 actor_id 存在，message 逐字为按
      operation_id,dispatch_id,adapter_id,chain_id 序的紧凑 JSON，
      状态为 approved（其后经 /sign 推进为 signed 亦认可）。

    任一不满足都是不可对账现场（RecoveryError，fail-closed，保留
    现场）。纯只读，不记事件、不改 seq、不写状态。"""
    events = self._dispatch_events_strict(wallet_id)
    if not events:
        return
    ledger = self._store.check_asset_ledger_semantics(wallet_id)
    operations = ledger["operations"]
    # 重放全部事件，取各操作的提交 seq 与各资产的策略历史（seq 升序）。

"""命令行入口。

与 HTTP 接口一一对应的三个客户端子命令（均打印单行 JSON）：
- create  对应 POST /v1/wallets
- sign    对应 POST /v1/wallets/<wallet_id>/sign
- show    对应 GET  /v1/wallets/<wallet_id>

另有两个本地命令：
- serve       启动 HTTP 服务
- share-sign  份额持有方辅助命令：用本机房份额私钥生成份额签名
              （签名内容为 signing_request_id 与 message 的拼接），
              输出可直接交给 sign 子命令的 {"share_id", "signature"}

客户端命令只通过 HTTP 与服务端交互；create/show 的响应中本就不含私钥。
"""

from __future__ import annotations

import argparse
import json
import sys
from typing import Optional, Sequence
from urllib import error as urllib_error
from urllib import request as urllib_request

DEFAULT_URL = "http://127.0.0.1:8080"
DEFAULT_DATA_DIR = "./data"
DEFAULT_HOST = "0.0.0.0"
DEFAULT_PORT = 8080


def _print_json(obj: dict) -> None:
    # 保留 dict 插入序：离线 backup/restore 的成功体有契约固定的顶层键序
    # （restore: status,wallet_id,snapshot_id,manifest_sha256,manifest；
    # backup: status,snapshot_id,manifest），sort_keys 会把它重排成字母序。
    print(json.dumps(obj, ensure_ascii=False))


def _fail(message: str) -> int:
    print(json.dumps({"error": message}, ensure_ascii=False), file=sys.stderr)
    return 1


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="threshold-wallet",
        description="两方门限（2-of-2）Ed25519 签名托管后端",
    )
    sub = parser.add_subparsers(dest="command", required=True)

    # serve
    p_serve = sub.add_parser("serve", help="启动 HTTP 服务")
    p_serve.add_argument("--host", default=DEFAULT_HOST)
    p_serve.add_argument("--port", type=int, default=DEFAULT_PORT)
    p_serve.add_argument("--data-dir", default=DEFAULT_DATA_DIR)

    # create  <-> POST /v1/wallets
    p_create = sub.add_parser("create", help="创建钱包（POST /v1/wallets）")
    p_create.add_argument("--url", default=DEFAULT_URL)
    p_create.add_argument("--wallet-id", required=True)
    p_create.add_argument("--shares", type=int, default=2, help="必须为 2")

    # show  <-> GET /v1/wallets/{id}
    p_show = sub.add_parser("show", help="查询钱包（GET /v1/wallets/{id}）")
    p_show.add_argument("--url", default=DEFAULT_URL)
    p_show.add_argument("--wallet-id", required=True)

    # sign  <-> POST /v1/wallets/{id}/sign
    p_sign = sub.add_parser("sign", help="提交两份份额签名（POST .../sign）")
    p_sign.add_argument("--url", default=DEFAULT_URL)
    p_sign.add_argument("--wallet-id", required=True)
    p_sign.add_argument("--signing-request-id", required=True)
    p_sign.add_argument("--message", required=True)
    p_sign.add_argument(
        "--signature",
        action="append",
        metavar="SHARE_ID=HEX",
        dest="signatures",
        required=True,
        help="份额签名，可重复两次；HEX 可由 share-sign 生成",
    )

    # policy  <-> PUT /v1/wallets/{id}/approval-policy
    p_policy = sub.add_parser(
        "policy", help="设置审批策略（PUT .../approval-policy）"
    )
    p_policy.add_argument("--url", default=DEFAULT_URL)
    p_policy.add_argument("--wallet-id", required=True)
    p_policy.add_argument("--required-approvals", type=int, required=True)
    p_policy.add_argument("--timeout-seconds", type=int, required=True)

    # request-create  <-> POST /v1/wallets/{id}/sign-requests
    p_rc = sub.add_parser(
