        "w1", {"ad2": "down", "ad1": "up"}
    )
    self.assertEqual(len(self._events()), 1)
    # 同值（乱序输入、归一后相等）不记
    self.svc.put_chain_adapters(
        "w1", {"ad1": "up", "ad2": "down"}
    )
    self.assertEqual(len(self._events()), 1)
    # 状态翻转 / 成员增删都记
    self.svc.put_chain_adapters(
        "w1", {"ad1": "down", "ad2": "down"}
    )
    self.assertEqual(len(self._events()), 2)
    self.svc.put_chain_adapters(
        "w1", {"ad1": "down"}
    )
    self.assertEqual(len(self._events()), 3)
    self.svc.put_chain_adapters(
        "w1", {"ad1": "down", "ad3": "up"}
    )
    self.assertEqual(len(self._events()), 4)
    # 再同值不记
    self.svc.put_chain_adapters(
        "w1", {"ad3": "up", "ad1": "down"}
    )
    self.assertEqual(len(self._events()), 4)

